<?php
namespace App\Http\Controllers;use App\Models\{Product,Brand,ProductCategory,Industry};use Illuminate\Http\Request;
class ProductController extends Controller {public function index(Request $r,?string $category=null){$q=Product::with(['brand','category'])->published()->search($r->q);if($category)$q->whereHas('category',fn($x)=>$x->where('slug',$category)->orWhereHas('parent',fn($p)=>$p->where('slug',$category)));if($r->brand)$q->whereHas('brand',fn($x)=>$x->where('slug',$r->brand));if($r->industry)$q->whereHas('industries',fn($x)=>$x->where('slug',$r->industry));return view('products.index',['products'=>$q->latest()->paginate(12)->withQueryString(),'brands'=>Brand::where('status',1)->orderBy('name')->get(),'categories'=>ProductCategory::where('status',1)->orderBy('name')->get(),'industries'=>Industry::where('status',1)->orderBy('name')->get(),'selectedCategory'=>$category]);}
public function show(Product $product){abort_unless($product->status,404);$product->increment('views');$product->load(['brand','category','images','attributes','documents','industries','applications']);$related=Product::with('brand')->published()->where('id','!=',$product->id)->where('category_id',$product->category_id)->take(4)->get();return view('products.show',compact('product','related'));}
public function compare(Request $r){$ids=array_slice(array_filter(explode(',',$r->get('ids',''))),0,4);$products=Product::with(['brand','attributes'])->published()->whereIn('id',$ids)->get();return view('products.compare',compact('products'));}}
